pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter: the new owner address to set. For any address 'newOwner',
    // if called by the current owner, the contract's public owner() should equal newOwner after the call.
    function testFuzz_property(address newOwner) public {
        // Ensure the caller is the current owner: setUp deployer is address(this) (test contract)
        // The constructor of C set owner = msg.sender which is this test contract during setUp().
        // So we must call setOwner as this contract.
        // Call setOwner(newOwner) and then assert that c.owner() == newOwner.

        // make the call as this test contract (we are already the deployer/owner)
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            // If it reverts, mark ok = false
            ok = false;
        }

        // The reference contract satisfies: after a successful call, c.owner() == newOwner.
        // We assert that either the call succeeded and the stored owner equals newOwner,
        // or the call reverted (ok == false) which should not happen for the reference but
        // the assertion must be a single assertTrue reading c's public surface. We encode the
        // universal property as: if the call returned true then c.owner() == newOwner.

        // To express this as a single assertTrue reading c, we read c.owner() and compare.
        // Build the predicate: ok implies c.owner() == newOwner  --> (!ok) || (c.owner() == newOwner)
        address stored = c.owner();
        assertTrue(!ok || stored == newOwner);
    }
}

