import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    // Fuzz the candidate address which we will try to set as the new owner.
    // We must let the fuzzer supply any address (EOA or contract); deploy a tiny helper contract
    // at that address when needed by creating a contract and then passing its address in.
    function testFuzz_property(address candidate) public {
        // Keep domain wide: exclude zero address only because constructor sets owner to deployer
        // and zero address is a valid candidate we still want to test — so do not assume.

        // The reference contract's rule to assert: when the current owner calls setOwner(candidate),
        // after the call c.owner() equals the supplied candidate. We will call setOwner as the owner.

        // Ensure the caller is the current owner (deployer set in setUp). Use prank to call as that owner.
        address currentOwner = address(this); // because setUp deployed c from this contract
        // Sanity: owner must equal this contract
        assertEq(c.owner(), currentOwner);

        // Call setOwner with the fuzzed candidate as the owner caller.
        vm.prank(currentOwner);
        bool ok;
        try c.setOwner(candidate) {
            ok = true;
        } catch {
            ok = false;
        }

        // The canonical reference behavior: the call should succeed (ok == true) and store exactly the supplied address.
        // We express a general universal property: for the reference contract, for every candidate the call returns successfully
        // (no revert) and afterwards c.owner() equals the candidate. We assert that property here.
        // This single assert reads c.owner() (public getter) and the ok flag obtained from invoking the call.
        assertTrue(ok && c.owner() == candidate);
    }
}

