pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameters: an address candidate 'candidate' which may be an EOA or a contract address.
    // We will deploy a tiny helper contract at that address by creating it from the fuzzed address-derived seed.
    // Since we cannot force the fuzzer to give us a pre-existing contract address, we instead fuzz a uint256
    // salt and deploy a minimal helper (so the candidate becomes a contract address). The deciding input is
    // the salt; the property must hold for all admissible salts under the reference and fail for some salt on the mutant.
    function testFuzz_property(uint256 deploySalt) public {
        // Keep domain wide but avoid the trivial zero-salt for clarity (still wide).
        // No restrictive assumes that would exclude bug-triggering inputs.
        // Deploy a minimal helper contract so the candidate address is a contract (has code).
        Helper h = new Helper{salt: bytes32(deploySalt)}();
        address candidate = address(h);

        // The current owner is the deployer of C (this contract's address is not owner), so prank as the owner.
        address owner = address(this);

        // The contract C setUp() used new C(), so owner is the test contract's address? Actually new C() sets owner = msg.sender,
        // and setUp was called by the test harness (this contract), so this contract is the owner and can call setOwner.
        // Call setOwner with the candidate contract address.
        bool ok;
        try c.setOwner(candidate) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract always completes successfully (returns true) and stores exactly the supplied address.
        // We therefore assert that the call succeeded and that the public getter equals the supplied candidate address.
        // This single assertion is a universal property the reference satisfies for all deploySalt; the mutant that uses
        // owner = payable(_owner) in the assignment can, for some contract addresses, produce a stored value
        // different from the non-payable-supplied address and thus violate this assertion for some fuzzed salts.
        assertTrue(ok && c.owner() == candidate);
    }
}

contract Helper {
    // minimal contract with no special behavior; existence as a contract (non-zero code) is what matters
    constructor() {}
}

