import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter is an address candidate to set as owner.
    // General rule: after a successful setOwner(a) call by the current owner,
    // the public getter c.owner() when converted to a non-payable address equals the supplied a.
    // The mutant that assigns owner = payable(a) may store a value that, when viewed as a plain address,
    // differs for some inputs; this test lets the fuzzer find such an a.
    function testFuzz_property(address candidate) public {
        // keep domain wide; disallow zero address to avoid trivialities but still wide enough
        // (zero address is admissible in original semantics, but disallowing it keeps fuzz effective)
        vm.assume(candidate != address(0));

        // caller must be current owner to pass onlyOwner modifier
        address owner = address(this); // setUp deployed c with msg.sender == address(this)
        // confirm current owner is this
        assertTrue(c.owner() == owner);

        // act as owner and call setOwner with the fuzzed candidate
        vm.prank(owner);
        bool ok;
        try c.setOwner(candidate) returns (bool success) { ok = success; } catch { ok = false; }

        // Only one assertion: for the reference contract this should always hold for all inputs.
        // We assert that, after a successful call, the stored owner when converted to plain address equals candidate.
        // This reads c via its public getter. The mutant (with payable(...) AST change) will fail this for some candidate.
        if (ok) {
            // convert stored owner to non-payable address and compare to supplied candidate
            assertTrue(address(c.owner()) == candidate);
        } else {
            // If the call failed (should not for correct contract when caller==owner), still assert false to catch mutation differences
            assertTrue(false);
        }
    }
}

