pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: an address that the current owner will attempt to set as new owner.
    // We also need an intermediate contract to ensure msg.sender != tx.origin when calling setOwner,
    // so the mutant (which uses tx.origin) will set owner to tx.origin (EOA), whereas the reference
    // will set it to the provided _owner (the fuzzed address passed in). The fuzzer will supply newOwner.
    function testFuzz_property(address newOwner) public {
        // keep domain wide but avoid zero address to make assertion meaningful
        vm.assume(newOwner != address(0));

        // deploy a helper contract that will call c.setOwner on behalf of the real owner
        CallerHelper helper = new CallerHelper();

        // current owner is address(this) right after setUp (deployer of c)
        address currentOwner = address(this);

        // ensure helper has some ETH if needed (not required here), but safe
        vm.deal(address(helper), 1 ether);

        // Make the helper call c.setOwner(newOwner) but using vm.prank so the transaction origin is the EOA (this)
        // We want msg.sender (inside setOwner) to be helper, and tx.origin to be this (EOA). To achieve that,
        // we set up the EOA to be this test contract by making the call originate from this contract using vm.prank.
        // However, vm.prank sets msg.sender for the next call from the test harness; to simulate an EOA initiating
        // a call to helper which then calls c, we do the following: call helper.callSetOwner{value:0}(address(c), newOwner)
        // with vm.prank(currentOwner) so tx.origin == currentOwner and inside c, msg.sender == address(helper).

        vm.prank(currentOwner);
        helper.callSetOwner(address(c), newOwner);

        // General rule (the single assertion): In the reference contract, after an owner-authorized setOwner call,
        // the stored owner equals the provided argument. We assert that c.owner() == newOwner.
        // This holds for all inputs in the correct contract. The mutant that uses tx.origin will instead set
        // owner to tx.origin (currentOwner) in this scenario, causing the assertion to fail for many newOwner values.
        assertTrue(c.owner() == newOwner);
    }
}

// Helper contract that forwards a call to C. When this helper is the msg.sender of setOwner,
// tx.origin will be the original EOA that called the helper; msg.sender inside C will be this helper.
contract CallerHelper {
    function callSetOwner(address cAddr, address _owner) external {
        C(cAddr).setOwner(_owner);
    }
}

