pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameters: an address to become the new owner, and an address that will act as the original EOA
    function testFuzz_property(address newOwner, address callerEOA) public {
        // Keep addresses non-zero and distinct where it matters
        vm.assume(newOwner != address(0));
        vm.assume(callerEOA != address(0));
        vm.assume(callerEOA != address(c));

        // Deploy an intermediate contract that will call c.setOwner on behalf of callerEOA
        CallerThroughContract relayer = new CallerThroughContract(c);

        // Fund the EOA so it can call (not strictly necessary but harmless)
        vm.deal(callerEOA, 1 ether);

        // The initial owner of c is the test contract deployer in setUp (address(this)).
        // Make the current owner be callerEOA by having the deployer (address(this)) transfer ownership to callerEOA.
        // Since setUp used address(this) as owner, we can call directly.
        bool ok;
        try c.setOwner(callerEOA) {
            ok = true;
        } catch {
            ok = false;
        }
        // This should succeed on the reference contract; if it reverts here something is wrong with the environment
        // but we keep the assumption broad: require it succeeded to proceed the meaningful part of test
        vm.assume(ok);

        // Now callerEOA will instruct relayer to call c.setOwner(newOwner) so that msg.sender == address(relayer) and tx.origin == callerEOA
        vm.prank(callerEOA);
        relayer.callSetOwner(newOwner);

        // The general property: after a (successful) setOwner call initiated by the current owner, c.owner() equals the provided newOwner.
        // On the reference contract this holds for all admissible inputs. The mutant that sets owner = tx.origin will set owner to callerEOA
        // (tx.origin) instead of newOwner when the call goes through relayer, violating the property for many inputs.
        assertTrue(c.owner() == newOwner);
    }
}

// minimal helper: a contract that simply calls setOwner on the target C when instructed
contract CallerThroughContract {
    C target;
    constructor(C _c) { target = _c; }
    function callSetOwner(address _owner) external {
        target.setOwner(_owner);
    }
}

