pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: the ownerCaller contract address (as address to deploy with CREATE2-like variety)
    // and the supplied newOwner address. We cannot fuzz-deploy an address directly, so we fuzz an address
    // value and newOwner; we will deploy a simple forwarder contract from that fuzzed address by using vm.prank
    // to make the deployer be the desired EOA owner. The forwarder will call c.setOwner(newOwner), making msg.sender
    // the forwarder contract and tx.origin the EOA used to deploy/call — ensuring msg.sender != tx.origin when calling through
    // the forwarder. We must ensure the EOA that is the initial owner is the one that constructed C (setUp uses test contract),
    // so we will make the test contract the initial owner and then transfer ownership to the EOA deployer by first calling
    // setOwner from the test contract (which is owner) to that EOA. Then that EOA will have the role of owner and will call
    // through the forwarder to setOwner(newOwner). The reference preserves newOwner, the mutant will set tx.origin.

    function testFuzz_property(address eoaCaller, address newOwner) public {
        // admissible domain: avoid zero addresses to keep behavior meaningful
        vm.assume(eoaCaller != address(0));
        vm.assume(newOwner != address(0));

        // Step 1: current owner is this test contract (deployer of C). Transfer ownership to the fuzzed EOA so it becomes owner.
        // The test contract calls c.setOwner(eoaCaller)
        bool ok;
        try c.setOwner(eoaCaller) {
            ok = true;
        } catch {
            ok = false;
        }
        // the reference must allow this (test contract is initial owner); require success to make rest meaningful
        assertTrue(ok);

        // Step 2: Deploy a small Forwarder contract from the EOA (so tx.origin == eoaCaller when it later calls),
        // but we need the EOA to be able to deploy: use vm.prank to make the next creation originate from eoaCaller.
        vm.prank(eoaCaller);
        Forwarder f = new Forwarder();

        // Step 3: Have the EOA call the forwarder so that the forwarder (msg.sender) calls c.setOwner(newOwner).
        // We simulate the EOA calling the forwarder by vm.prank(eoaCaller) and invoking Forwarder.forwardSetOwner.
        vm.prank(eoaCaller);
        try f.forwardSetOwner(payable(address(c)), newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: after the forwarder (msg.sender) which is different from tx.origin invokes c.setOwner(newOwner),
        // the reference contract C will set owner to the supplied newOwner (getter owner()), whereas the mutant that uses tx.origin
        // would set owner to tx.origin (the EOA eoaCaller) and thus differ for inputs where eoaCaller != newOwner.
        // We assert the reference property: c.owner() == newOwner.
        assertTrue(c.owner() == newOwner);
    }
}

contract Forwarder {
    function forwardSetOwner(address payable caddr, address newOwner) external {
        // call C.setOwner(newOwner)
        C(caddr).setOwner(newOwner);
    }
}

