pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an address ownerProxy which will act as an intermediate contract's deployer (owner)
    // and an address newOwner which is the intended new owner passed into setOwner
    function testFuzz_property(address ownerProxy, address newOwner) public {
        // keep addresses non-zero and distinct to avoid trivialities
        vm.assume(ownerProxy != address(0));
        vm.assume(newOwner != address(0));

        // Deploy an intermediate contract that will call c.setOwner on behalf of the owner
        // The intermediate's call will make msg.sender == intermediate, tx.origin == ownerProxy
        OwnerCaller intermediate = new OwnerCaller(c);

        // Fund ownerProxy so it can call via intermediate (not strictly necessary for EOAs, but safe)
        vm.deal(ownerProxy, 1 ether);

        // Make ownerProxy the initial owner of c by constructing c as setUp() already did (owner = address(this of deployer))
        // c was deployed by this test contract, so current owner is address(this). We need ownerProxy to be owner.
        // To make ownerProxy the owner, have the current owner (this) call setOwner(ownerProxy)
        bool ok;
        try c.setOwner(ownerProxy) {
            ok = true;
        } catch {
            ok = false;
        }
        // sanity: reference contract should allow this (we are owner), so ok must be true for admissible domain
        // but do not assert here — single assert required at end

        // Now ownerProxy will call through the intermediate contract to set owner to newOwner.
        // We need ownerProxy to be the tx.origin of that call while intermediate is msg.sender in c.
        vm.prank(ownerProxy);
        intermediate.callSetOwner(newOwner);

        // The general rule (for the reference): when the owner (ownerProxy) calls setOwner(newOwner) through an intermediate contract
        // where msg.sender != tx.origin, the reference contract still sets owner == newOwner because it uses the provided argument.
        // The mutant that assigns owner = tx.origin would set owner == ownerProxy instead.
        assertTrue(c.owner() == newOwner);
    }
}

contract OwnerCaller {
    C immutable target;
    constructor(C _target) { target = _target; }
    function callSetOwner(address _newOwner) external {
        // forward the call as msg.sender == this contract, tx.origin == original EOA
        target.setOwner(_newOwner);
    }
}

