pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: actor (the original owner) and target (the new owner to set)
    // We will deploy a small Forwarder contract that will call c.setOwner(target) from itself,
    // while tx.origin will be actor. On the correct contract, only msg.sender (the Forwarder)
    // is checked, so only if the Forwarder equals current owner will the change succeed.
    // In our test we assert the universal property: after a direct call by actor to setOwner(target),
    // owner == target iff actor was previous owner. To exercise the mutant difference, we instead
    // have actor call through Forwarder: the reference contract still requires msg.sender == owner
    // (so Forwarder must be owner to change it), while the mutant that uses tx.origin would accept actor==owner
    // even though msg.sender is Forwarder. We assert that a direct-prank call (actor calling through Forwarder)
    // does NOT change owner unless the Forwarder was already owner — the reference satisfies this for all inputs,
    // the mutant is violated for some inputs (when actor==initial owner but Forwarder != initial owner).

    function testFuzz_property(address actor, address target) public {
        // keep addresses non-zero to avoid edge cases; allow fuzzer wide domain otherwise
        vm.assume(actor != address(0));
        vm.assume(target != address(0));
        // Ensure actor is not the same as the test contract deployer (which is initial owner)
        // but do NOT over-constrain: we allow all combos. We'll set up balances so actor can call.

        // Deploy a Forwarder contract that will call c.setOwner(target) from its address
        Forwarder f = new Forwarder(c);

        // Ensure actor has some ETH so they can call through the forwarder if needed (not required here but harmless)
        vm.deal(actor, 1 ether);

        // Snapshot current owner
        address initialOwner = c.owner();

        // Actor will instruct the Forwarder to call c.setOwner(target). We prank as actor so tx.origin==actor and msg.sender==Forwarder.
        vm.startPrank(actor);
        // encode a call to the Forwarder's doCall(target)
        f.doCall(target);
        vm.stopPrank();

        // After the forwarded call, on the correct contract the owner should be changed only if msg.sender (Forwarder)
        // equaled initialOwner; otherwise it must remain initialOwner. This is the universal property we assert.
        bool forwarderWasOwner = (address(f) == initialOwner);
        if (forwarderWasOwner) {
            // If forwarder was owner, the change should succeed and owner == target
            assertTrue(c.owner() == target);
        } else {
            // If forwarder was not owner, the change should NOT have happened; owner remains initialOwner
            assertTrue(c.owner() == initialOwner);
        }
    }
}

// Minimal helper Forwarder that calls C.setOwner on behalf of an originator
contract Forwarder {
    C immutable c;
    constructor(C _c) { c = _c; }
    function doCall(address newOwner) external {
        // call c.setOwner from this contract (msg.sender == this contract, tx.origin is the external caller)
        c.setOwner(newOwner);
    }
}

