pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter: an arbitrary caller address that may or may not be the owner
    function testFuzz_property(address caller) public {
        // keep caller wide but not the zero address (optional, still wide)
        vm.assume(caller != address(0));

        // Ensure the deployer (this contract) is the initial owner per C constructor
        address initialOwner = address(this);
        assertTrue(c.owner() == initialOwner);

        // The general rule: only the current owner can change owner via setOwner.
        // We test by having `caller` attempt to set owner to itself.

        // Fund caller so vm.prank can send transactions (not strictly needed for non-payable)
        vm.deal(caller, 1 ether);

        // Have the fuzzed caller attempt to call setOwner(caller)
        vm.prank(caller);
        bool ok;
        try c.setOwner(caller) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference contract: if caller != initialOwner then call must fail (or not change owner)
        // We assert the universal property: after the attempt, owner is either unchanged (still initialOwner)
        // or, if caller was the initial owner, it may have changed to caller. This single assertion
        // distinguishes the correct contract (which enforces onlyOwner) from the mutant (which allows
        // arbitrary callers to become owner). Concretely: owner() == initialOwner || owner() == caller
        assertTrue(c.owner() == initialOwner || c.owner() == caller);
    }
}

