pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed actor: an arbitrary address that will attempt to call setOwner
    function testFuzz_property(address attacker, address newOwner) public {
        // keep addresses in wide admissible domain; avoid zero address for clarity
        vm.assume(attacker != address(0));
        vm.assume(newOwner != address(0));

        // The reference contract requires onlyOwner, so only the deployer (owner) can change owner.
        // We test that for ANY attacker address, when that attacker calls setOwner, the contract's owner
        // remains unchanged (i.e., still the deployer). The mutant that removes the check will allow
        // some attacker to change the owner, so this assertion will fail on the mutant for some inputs.

        // record current owner (deployer)
        address originalOwner = c.owner();

        // have attacker attempt to call setOwner
        vm.prank(attacker);
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // Exactly one assertion: the owner must still be the original deployer for ALL inputs on the correct contract.
        // (This will fail on the mutant for some attacker/newOwner fuzz inputs because the mutant allows anyone to set owner.)
        assertTrue(c.owner() == originalOwner);
    }
}

