pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: caller (the actor that will be the current owner and then call setOwner)
    // and newOwner (the address to set). The property: if caller is the current owner, then calling
    // setOwner(newOwner) from caller should succeed and then c.owner() == newOwner.
    function testFuzz_property(address caller, address newOwner) public {
        // Keep domain wide but avoid zero-address for caller because constructor set owner to test contract deployer (address(this) in setUp),
        // we want to allow the fuzzer to pick any caller; we will make `caller` become the contract owner by impersonation.
        // Do not exclude values that could reveal the bug. Only avoid the trivial case where caller == address(0) as a sender
        // cannot be pranked to (EVM allows address(0) as msg.sender in tests, but it is atypical). Still keep allowance wide.
        // No tight vm.assume to avoid excluding bug-revealing inputs.

        // Make `caller` the current owner by calling setOwner from the original owner (deployer of c is this contract)
        // First, ensure this contract (address(this)) is current owner (it is, from setUp()). So set owner to caller.
        bool ok;
        // set owner to caller from the true owner (this) should succeed on reference implementation
        try c.setOwner(caller) {
            ok = true;
        } catch {
            ok = false;
        }
        // If even this initial step failed (very unlikely on reference), skip assertion by assuming it succeeded; keep domain wide.
        vm.assume(ok);

        // Now impersonate caller and attempt to set owner to newOwner
        vm.prank(caller);
        bool ok2;
        try c.setOwner(newOwner) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // Exactly one assertion reading c's public getter: on the reference implementation, if caller was the owner,
        // the call should succeed (ok2 == true) and c.owner() should equal newOwner. We assert that if the call returned ok2==true,
        // then owner() == newOwner. This is a universal property the reference satisfies for all inputs; the mutant makes
        // calls from real callers revert (ok2==false) so there will exist fuzzed inputs where ok2==false and owner() != newOwner,
        // causing the single assertTrue below to fail for those inputs when run against the mutant.
        // We express the property as: the boolean (ok2 && c.owner() == newOwner) is always true after the caller (who is current owner)
        // calls setOwner(newOwner). Since we arranged caller to be the owner above, this must hold.
        assertTrue(ok2 && (c.owner() == newOwner));
    }
}

